#!/usr/bin/env python3
from scapy.all import *
import collections

pkts = rdpcap('/home/ctfplayer/ctf_files/capture.pcapng')
print("total packets:", len(pkts))

convos = collections.Counter()
for p in pkts:
    if IP in p:
        key = (p[IP].src, p[IP].dst, p.sport if hasattr(p,'sport') else None, p.dport if hasattr(p,'dport') else None)
        convos[key]+=1
for k,v in convos.most_common():
    print(k, v)

arguments.command:
cd /home/ctfplayer/workspace && python3 - <<'EOF'
from scapy.all import *
pkts = rdpcap('/home/ctfplayer/ctf_files/capture.pcapng')
# reassemble TCP streams
streams = {}
for i,p in enumerate(pkts):
    if IP in p and TCP in p:
        key = (p[IP].src, p[TCP].sport, p[IP].dst, p[TCP].dport)
        streams.setdefault(key, b'')
        streams[key] += bytes(p[TCP].payload) if p[TCP].payload else b''
for k,v in streams.items():
    print(k, len(v), v[:8].hex())
EOF

cd /home/ctfplayer/workspace && python3 -c "
from scapy.all import *
pkts = rdpcap('/home/ctfplayer/ctf_files/capture.pcapng')
for i,p in enumerate(pkts):
    if IP in p and TCP in p:
        pl = bytes(p[TCP].payload)
        if pl[:1]==b'\x16' and pl[5:6]==b'\x01':
            print('ClientHello at pkt', i, p[IP].src, p[IP].dst, pl[11:43].hex())
"

