{"command": "cd /home/ctfplayer/workspace && python3 - <<'EOF'
import pefile
for f in ['vcheck/vcheck.exe','vcheck/version.dll']:
    pe = pefile.PE(f)
    print('=====', f, 'machine', hex(pe.FILE_HEADER.Machine), 'ts', pe.FILE_HEADER.TimeDateStamp)
    print('sections:')
    for s in pe.sections:
        print('  ', s.Name.rstrip(b'\0'), hex(s.VirtualAddress), hex(s.SizeOfRawData), 'entropy', round(s.get_entropy(),3))
    print('imports:')
    for e in pe.DIRECTORY_ENTRY_IMPORT:
        print('  ', e.dll.decode(), [imp.name.decode() if imp.name else imp.ordinal for imp in e.imports])
EOF"}

